import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.D7xI0JV8.js";const f=JSON.parse('{"title":"The Primitive","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),i={name:"intro.md"};function n(s,e,l,h,c,d){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-primitive" tabindex="-1">The Primitive <a class="header-anchor" href="#the-primitive" aria-label="Permalink to &quot;The Primitive&quot;">​</a></h1><h2 id="what-zkde-fi-is" tabindex="-1">What zkde.fi Is <a class="header-anchor" href="#what-zkde-fi-is" aria-label="Permalink to &quot;What zkde.fi Is&quot;">​</a></h2><p>zkde.fi is a reference implementation of proof-gated private finance built on top of the <a href="https://obsqra.xyz" target="_blank" rel="noreferrer">Obsqra Labs</a> proving infrastructure. It is not a DeFi app. The DeFi surfaces — Capital OS, Trade Desk, privacy vaults — are demonstrations of the proof system working in production.</p><p>The parent infrastructure layer is <a href="https://starkforge.xyz" target="_blank" rel="noreferrer">StarkForge</a>. zkde.fi is one application built on top of it.</p><h2 id="the-gap-this-closes" tabindex="-1">The Gap This Closes <a class="header-anchor" href="#the-gap-this-closes" aria-label="Permalink to &quot;The Gap This Closes&quot;">​</a></h2><p>On-chain execution is trustless — smart contracts enforce rules deterministically. Off-chain computation is not. When an AI model says &quot;this pool is safe&quot; or &quot;allocate 40% here,&quot; there is no cryptographic guarantee that the model ran correctly, that the inputs were real, or that the output wasn&#39;t manipulated.</p><p>The primitive closes that gap: <strong>off-chain computation produces on-chain-verifiable proof before capital moves.</strong></p><h2 id="the-architecture-snark-in-stark-dual-lane" tabindex="-1">The Architecture: SNARK-in-STARK Dual Lane <a class="header-anchor" href="#the-architecture-snark-in-stark-dual-lane" aria-label="Permalink to &quot;The Architecture: SNARK-in-STARK Dual Lane&quot;">​</a></h2><p>zkde.fi uses a dual-lane proving architecture:</p><ul><li><p><strong>SNARK lane (Garaga/Groth16):</strong> EZKL converts ML model inference into Groth16 proofs. These are verified on-chain via Garaga&#39;s BN254 pairing check implemented natively in Cairo. This lane handles zkML verification — proving that a specific model produced a specific output from specific inputs.</p></li><li><p><strong>STARK lane (Stone):</strong> The same STARK prover infrastructure that generates validity proofs for Starknet blocks. This lane handles execution integrity — proving that the full computation (policy checks, gate evaluation, settlement routing) executed correctly.</p></li></ul><p>When both lanes are active (<code>FULL_DUAL_PROVER</code> mode), a single action produces two independent cryptographic guarantees: the AI output is correct (SNARK), and the execution that consumed it was faithful (STARK).</p><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20SIG%5BSignal%20%2F%20intent%5D%20--%3E%20EZKL%5BEZKL%20inference%5D%0A%20%20EZKL%20--%3E%20G16%5BGroth16%20proof%5D%0A%20%20G16%20--%3E%20GAR%5BGaraga%20KZG%20check%20in%20Cairo%5D%0A%20%20GAR%20--%3E%20STONE%5BStone%20STARK%20envelope%5D%0A%20%20STONE%20--%3E%20GATE%5BPolicy%20gate%5D%0A%20%20GATE%20--%3E%20SETTLE%5BSettlement%20%2B%20receipt%5D%0A%20%20SETTLE%20--%3E%20L3%5BMadara%20L3%20fact%20registry%5D">flowchart LR
  SIG[Signal / intent] --&gt; EZKL[EZKL inference]
  EZKL --&gt; G16[Groth16 proof]
  G16 --&gt; GAR[Garaga KZG check in Cairo]
  GAR --&gt; STONE[Stone STARK envelope]
  STONE --&gt; GATE[Policy gate]
  GATE --&gt; SETTLE[Settlement + receipt]
  SETTLE --&gt; L3[Madara L3 fact registry]</pre><h2 id="what-the-system-can-prove" tabindex="-1">What The System Can Prove <a class="header-anchor" href="#what-the-system-can-prove" aria-label="Permalink to &quot;What The System Can Prove&quot;">​</a></h2><ol><li><strong>Input provenance</strong> — the data fed to a model came from a verified source (oracle, on-chain state, committed private input)</li><li><strong>Model integrity</strong> — the ML model that produced a recommendation is the same model whose weights were committed on-chain via KZG</li><li><strong>Execution constraints</strong> — the transaction that resulted from the recommendation respected slippage bounds, allocation limits, and policy gates</li><li><strong>Policy compliance</strong> — the user&#39;s trust posture (reputation tier, collateral ratio, proof history) met the minimum threshold for the action</li><li><strong>Settlement finality</strong> — the proof was registered on Madara L3 (or Starknet L2 fallback) and is independently verifiable via block explorer</li></ol><h2 id="what-s-deployed-right-now" tabindex="-1">What&#39;s Deployed Right Now <a class="header-anchor" href="#what-s-deployed-right-now" aria-label="Permalink to &quot;What&#39;s Deployed Right Now&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Network</th><th>Contracts</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Starknet Sepolia</strong></td><td>ZkmlVerifier, ModelBridgeVerifier, GaragaVerifier, ReputationRegistry, VaultController, ObsqraFactRegistry, ReceiptRegistry, DAOConstraintManager, 5 FICO-pack verifiers, and more</td><td><a href="https://sepolia.voyager.online/contract/0x068abd64a4a78172a5ee15a30bbe614257d62482f07d3ff7fdb72da5aad08923" target="_blank" rel="noreferrer">ZkmlVerifier on Voyager</a></td></tr><tr><td><strong>Ethereum Sepolia</strong></td><td>Halo2Verifier (EZKL KZG), L1 Bridge Sender</td><td><a href="https://sepolia.etherscan.io/address/0xF7b555ca4E54a8c7B9A0DDBFa17341575a852Ab9" target="_blank" rel="noreferrer">Halo2Verifier on Etherscan</a></td></tr><tr><td><strong>Madara L3</strong></td><td>VerifiedFactRegistry</td><td>Dedicated appchain for proof fact registration</td></tr></tbody></table><ul><li><strong>31</strong> Circom circuits compiled to WASM + zkey</li><li><strong>2</strong> EZKL ML models (yield forecast, anomaly detector) with Halo2/KZG proofs</li><li><strong>136+</strong> on-chain trust receipts</li><li><strong>5</strong> verified proof lanes: Groth16 (Garaga), STARK (Stone), Noir HONK, Native KZG, hash-only fallback</li></ul><p>Full live verification: <strong><a href="https://zkde.fi/test" target="_blank" rel="noreferrer">zkde.fi/test</a></strong></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/proof-readout">Live Proof Readout</a> — see every claim verified at zkde.fi/test</li><li><a href="/docs/proof-pipeline">Proof Pipeline</a> — ProofMode table, verifier lanes, settlement paths</li><li><a href="/docs/contracts">Deployed Contracts</a> — full on-chain contract map</li></ul>`,20)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
